package com.cpf.education.online.concurrency.service;
import com.cpf.core.api.error.*;import com.cpf.data.persistence.api.CpfCrudRepository;import com.cpf.data.persistence.api.annotation.CpfTransactional;import com.cpf.education.online.concurrency.model.MemberVersion;import com.cpf.foundation.annotation.CpfService;import org.springframework.beans.factory.ObjectProvider;
/** 동시성 제어 교육 예제의 Service 역할과 CPF 표준 사용 경계를 보여줍니다. */
@CpfService public class MemberPreferenceService {private final ObjectProvider<CpfCrudRepository<MemberVersion,String>> repositories;public MemberPreferenceService(ObjectProvider<CpfCrudRepository<MemberVersion,String>> r){repositories=r;}@CpfTransactional public MemberVersion update(MemberVersion c){var repo=repository();var current=repo.findById(c.memberId()).orElseThrow(()->new CpfNotFoundException("회원이 없습니다: "+c.memberId()));if(current.version()!=c.version())throw new CpfBusinessException(CpfErrorCode.CONFLICT,"이미 다른 거래가 변경했습니다. 최신 값을 다시 조회하십시오.");return repo.save(new MemberVersion(c.memberId(),c.value(),c.version()+1));}private CpfCrudRepository<MemberVersion,String> repository(){var r=repositories.getIfAvailable();if(r==null)throw new IllegalStateException("CPF repository provider is not configured");return r;}}
